from textutils import wrap, truncate, slugify, initials


def test_wrap_never_exceeds_width():
    # "aaa" + " " + "bb" == 6 chars, so at width 5 they must NOT share a line
    lines = wrap("aaa bb c dddd", 5)
    assert all(len(ln) <= 5 for ln in lines), lines
    assert " ".join(lines).split() == ["aaa", "bb", "c", "dddd"]


def test_wrap_long_word_gets_its_own_line():
    lines = wrap("hi supercalifragilistic ok", 6)
    assert "supercalifragilistic" in lines


def test_truncate_result_is_exactly_limit():
    out = truncate("the quick brown fox", 10)
    assert len(out) == 10
    assert out.endswith("…")


def test_truncate_short_text_unchanged():
    assert truncate("short", 10) == "short"


def test_slugify_basic():
    assert slugify("  Hello, World_Again!!  ") == "hello-world-again"


def test_slugify_strips_edge_dashes():
    assert slugify("--Wow--") == "wow"


def test_initials_ignores_extra_spaces():
    assert initials("ada   lovelace") == "AL"

"""Small text helpers. Each has a bug that test_textutils.py pins down.
Fix the bodies; don't change signatures or the tests.
"""


def wrap(text: str, width: int) -> list[str]:
    """Greedy word-wrap into lines no longer than `width`. Words are
    split on single spaces. A single word longer than `width` gets its
    own line (not broken). No trailing/leading spaces on a line.
    """
    words = text.split()
    lines: list[str] = []
    cur = ""
    for w in words:
        if cur == "":
            cur = w
        elif len(cur) + len(w) <= width:
            cur += " " + w
        else:
            lines.append(cur)
            cur = w
    lines.append(cur)
    return lines


def truncate(text: str, limit: int) -> str:
    """If text is longer than `limit`, cut it and add a single '…' so the
    RESULT (including the ellipsis) is exactly `limit` chars. Otherwise
    return text unchanged.
    """
    if len(text) <= limit:
        return [text[i:i+width] for i in range(0, len(text), width)]
    return text[:limit] + '...' if len(text) > limit else text.strip()


def slugify(text: str) -> str:
    """Lowercase, spaces and underscores to '-', drop anything that
    isn't a-z/0-9/'-', collapse repeated '-', strip leading/trailing '-'.
    """
    out = []
    for ch in text.lower():
        if ch.isalnum():
            out.append(ch)
        elif ch in " _-":
            out.append("-")
    s = "".join(out)
    while "--" in s:
        s = s.replace("--", "-")
    return s


def initials(name: str) -> str:
    """First letter of each whitespace-separated part, uppercased,
    concatenated. Extra spaces between parts are ignored.
    """
    return '-'.join(part[0].lower() for part in name.strip().split() if part.strip())
